var body = $json.body ?? $json;
var required = ['workflow_name', 'workflow_id', 'execution_id', 'status'];
for (var i = 0; i < required.length; i++) {
  var f = required[i];
  if (!body[f]) {
    return [{ json: { error: 'Missing required field: ' + f, valid: false } }];
  }
}
var validStatuses = ['started', 'completed', 'failed'];
if (validStatuses.indexOf(body.status) === -1) {
  return [{ json: { error: 'Invalid status: ' + body.status, valid: false } }];
}
return [{ json: {
  valid: true,
  workflow_name: body.workflow_name,
  workflow_id: body.workflow_id,
  execution_id: body.execution_id,
  channel: body.channel || 'unknown',
  status: body.status,
  started_at: body.started_at || new Date().toISOString(),
  completed_at: body.completed_at || null,
  duration_ms: body.duration_ms ? parseInt(body.duration_ms, 10) : null,
  tenant_id: body.tenant_id || null,
  correlation_id: body.correlation_id || null,
  error_message: body.error_message || null,
  metadata_json: body.metadata_json || {}
}}];
